        ...process.env,
        ...(process.env.COMET_NATIVE_BASELINE_PACKAGE
          ? { COMET_TEST_SOURCE_APPLICATION: '0' }
          : { COMET_TEST_LEGACY_NATIVE: '1' }),
      },
      timeout: 120000,
    },
  );
  return JSON.parse(output) as {
    projectRoot: string;
    name: string;
    file: string;
    run: WorkflowRun;
    sibling: WorkflowRun['actions'][number];
  };
}

