      await expect(inspectNativeWorkspaceFinishCompletion(paths, journal)).resolves.toBe(false);
      git(['update-index', '--no-assume-unchanged', '--', ref]);
      await fs.unlink(altered);
      await expect(inspectNativeWorkspaceFinishCompletion(paths, journal)).resolves.toBe(false);
    },
  );

