    await confirmNativePortableShape({ paths: secondaryPaths, name: 'secondary-owner' });

    await expect(inspectNativePortableArchive({ paths, name: first.name })).resolves.toMatchObject({
      ready: false,
      capabilityPeers: ['secondary-owner'],
    });
