    runId: options.name,
    revision: 7,
    status: 'active',
    workflow: { id: 'comet-native', version: '1', hash: 'fixture' },
    input: { name: options.name, artifactRootRef: 'docs' },
    state,
    actions: [archiveAction()],
    waits: [],
    evidenceWaits: [],
    ready: [],
  } as unknown as WorkflowRun;
  return { run, state, artifactRootRef: 'docs', application: null };
}
